mapper.select:
SELECT SUB_ID, KAKAO_ID, ENDPOINT, P256DH, AUTH, USER_AGENT
FROM TCAR_PUSH_SUB
WHERE KAKAO_ID = #{kakaoId}

mapper.insert:
INSERT INTO TCAR_PUSH_LOG (
    LOG_ID, SENT_AT, TYPE, TARGET_KAKAO_ID, SUB_ID, ACTOR_KAKAO_ID, ACTOR_NAME,
    TITLE, BODY, RESULT, HTTP_CODE, ERROR_MSG
) VALUES (
    TCAR_PUSH_LOG_SEQ.NEXTVAL, SYSDATE, #{type}, #{targetKakaoId, jdbcType=VARCHAR}, #{subId, jdbcType=NUMERIC},
    #{actorKakaoId, jdbcType=VARCHAR}, #{actorName, jdbcType=VARCHAR},
    #{title, jdbcType=VARCHAR}, #{body, jdbcType=VARCHAR}, #{result},
    #{httpCode, jdbcType=NUMERIC}, #{errorMsg, jdbcType=VARCHAR}
)

mapper.select:
SELECT (SYSDATE - MAX(SENT_AT)) * 24 * 60
FROM TCAR_PUSH_LOG
WHERE ACTOR_KAKAO_ID = #{actorKakaoId} AND TYPE = #{type}
